  q(MOD,'Forensic DNA profiles in the United States compare which regions?','Short tandem repeats',['Whole genes for eye color','Mitochondrial rRNA genes','Entire chromosomes'],'B','STR repeat lengths vary between people; matches across many loci are highly specific.',CAR)
